BEGIN;
CREATE OR REPLACE FUNCTION public.office_institutions_command(p_workspace_id uuid,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE k uuid:=NULLIF(p_payload->>'idempotency_key','')::uuid; h text:=md5(p_action||':'||p_payload::text); old jsonb; r text:=p_payload->>'resource'; record_id uuid; v bigint; st text; d jsonb:=COALESCE(p_payload->'data','{}'); merged jsonb; cap text; resp jsonb; expected bigint; branch uuid; x record; settings record; idem_action text; idem_hash text; key_name text; allowed text[]; BEGIN
 IF NOT office_private.inst_member(p_workspace_id) THEN RAISE EXCEPTION 'Active Institutions industry membership required' USING ERRCODE='42501'; END IF;
 IF p_action IS NULL OR jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Invalid Institutions command' USING ERRCODE='22023'; END IF;
 allowed:=CASE p_action
   WHEN 'initialize' THEN ARRAY['idempotency_key']
   WHEN 'assign_role' THEN ARRAY['user_id','role','branch_id','active','expected_version','idempotency_key']
   WHEN 'save_record' THEN ARRAY['resource','id','expected_version','data','idempotency_key']
   WHEN 'save_private' THEN ARRAY['resource','id','expected_version','data','idempotency_key']
   WHEN 'transition_record' THEN ARRAY['resource','id','to_state','expected_version','data','idempotency_key']
   WHEN 'post_asset_move' THEN ARRAY['resource','id','expected_version','idempotency_key']
   WHEN 'create_report' THEN ARRAY['report_type','title','period_start','period_end','branch_id','idempotency_key']
   WHEN 'export_report' THEN ARRAY['id','expected_version','purpose','idempotency_key']
   WHEN 'configure_settings' THEN ARRAY['expected_version','base_currency','idempotency_key']
   WHEN 'configure_private_key' THEN ARRAY['expected_version','kind','salt','nonce','ciphertext','idempotency_key']
   WHEN 'record_storage_review' THEN ARRAY['expected_version','reference','idempotency_key']
   WHEN 'review_storage' THEN ARRAY['expected_version','decision','reference','idempotency_key']
   WHEN 'set_private_gate' THEN ARRAY['expected_version','enabled','idempotency_key']
   WHEN 'post_contribution' THEN ARRAY['id','expected_version','idempotency_key']
   WHEN 'void_contribution' THEN ARRAY['id','expected_version','reason','reference','idempotency_key']
   WHEN 'approve_payment' THEN ARRAY['id','expected_version','idempotency_key']
   WHEN 'post_payment' THEN ARRAY['id','expected_version','method','reference','idempotency_key']
   WHEN 'close_reconciliation' THEN ARRAY['id','expected_version','idempotency_key']
   ELSE NULL END;
 IF allowed IS NULL THEN RAISE EXCEPTION 'Unknown Institutions action' USING ERRCODE='22023'; END IF;
 FOR key_name IN SELECT jsonb_object_keys(p_payload) LOOP IF NOT (key_name=ANY(allowed)) THEN RAISE EXCEPTION 'Unknown command field %',key_name USING ERRCODE='22023'; END IF; END LOOP;
 IF p_action<>'initialize' AND NOT (p_action='initialize' AND EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=auth.uid() AND m.role='owner' AND m.status='active') AND NOT EXISTS(SELECT 1 FROM public.office_institutions_roles r0 WHERE r0.workspace_id=p_workspace_id AND r0.active)) THEN PERFORM office_private.inst_require(p_workspace_id); END IF; IF k IS NULL THEN RAISE EXCEPTION 'idempotency_key required' USING ERRCODE='22023'; END IF; INSERT INTO public.office_institutions_idempotency(workspace_id,actor_id,idempotency_key,action,request_hash,response) VALUES(p_workspace_id,auth.uid(),k,p_action,h,'{}'::jsonb) ON CONFLICT DO NOTHING; SELECT response,action,request_hash INTO old,idem_action,idem_hash FROM public.office_institutions_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=k FOR UPDATE; IF old IS NOT NULL AND old<>'{}'::jsonb THEN IF idem_action<>p_action OR idem_hash<>h THEN RAISE EXCEPTION 'Idempotency key replay differs' USING ERRCODE='22023'; END IF; RETURN old; END IF;
 IF p_action='initialize' THEN IF NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=auth.uid() AND m.role='owner' AND m.status='active') THEN RAISE EXCEPTION 'Only workspace owner may initialize' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id AND initialized) OR EXISTS(SELECT 1 FROM public.office_institutions_roles WHERE workspace_id=p_workspace_id) THEN RAISE EXCEPTION 'Institutions already initialized' USING ERRCODE='55000'; END IF; INSERT INTO public.office_institutions_settings(workspace_id,initialized) VALUES(p_workspace_id,true); INSERT INTO public.office_institutions_roles(workspace_id,user_id,role) VALUES(p_workspace_id,auth.uid(),'institution_admin'); resp:=jsonb_build_object('status','initialized','version',1); ELSE
 IF p_action='assign_role' THEN IF NOT office_private.inst_cap(p_workspace_id,'manage') THEN RAISE EXCEPTION 'Role assignment denied' USING ERRCODE='42501'; END IF; IF p_payload->>'role' NOT IN('institution_admin','registrar','governance_secretary','treasurer','approver','facility_manager','programme_coordinator','hr_officer','safeguarding_officer','privacy_officer','institution_viewer') THEN RAISE EXCEPTION 'Invalid role' USING ERRCODE='22023'; END IF; IF p_payload ? 'active' AND jsonb_typeof(p_payload->'active')<>'boolean' THEN RAISE EXCEPTION 'active must be boolean' USING ERRCODE='22023'; END IF; IF p_payload ? 'expected_version' AND ((p_payload->>'expected_version') IS NULL OR (p_payload->>'expected_version')::bigint<1) THEN RAISE EXCEPTION 'Positive expected_version required' USING ERRCODE='22023'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=(p_payload->>'user_id')::uuid AND m.status='active') THEN RAISE EXCEPTION 'Role target must be an active Office member' USING ERRCODE='42501'; END IF; IF (p_payload->>'user_id')::uuid=auth.uid() AND ((p_payload ? 'active' AND (p_payload->>'active')::boolean=false) OR p_payload->>'role' <> 'institution_admin') AND (SELECT count(*) FROM public.office_institutions_roles ar WHERE ar.workspace_id=p_workspace_id AND ar.role='institution_admin' AND ar.active)<2 THEN RAISE EXCEPTION 'Cannot remove the last active institution admin' USING ERRCODE='42501'; END IF; branch:=NULLIF(p_payload->>'branch_id','')::uuid; IF branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_institutions_records b WHERE b.workspace_id=p_workspace_id AND b.resource='branches' AND b.id=branch) THEN RAISE EXCEPTION 'Unknown branch' USING ERRCODE='22023'; END IF; PERFORM office_private.inst_assert_scope(p_workspace_id,branch); IF EXISTS(SELECT 1 FROM public.office_institutions_roles ar WHERE ar.workspace_id=p_workspace_id AND ar.user_id=(p_payload->>'user_id')::uuid) THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'Positive expected_version required for existing role' USING ERRCODE='22023'; END IF; UPDATE public.office_institutions_roles SET role=p_payload->>'role',branch_id=branch,active=COALESCE((p_payload->>'active')::boolean,true),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid AND version=(p_payload->>'expected_version')::bigint; IF NOT FOUND THEN RAISE EXCEPTION 'Stale role version' USING ERRCODE='40001'; END IF; ELSE IF p_payload ? 'expected_version' THEN RAISE EXCEPTION 'Create cannot include expected_version' USING ERRCODE='22023'; END IF; INSERT INTO public.office_institutions_roles(workspace_id,user_id,role,branch_id,active) VALUES(p_workspace_id,(p_payload->>'user_id')::uuid,p_payload->>'role',branch,COALESCE((p_payload->>'active')::boolean,true)); END IF; resp:=jsonb_build_object('status','assigned');
 ELSIF p_action='save_record' AND r IN('funds','budgets','contributions','payment_requests','bank_lines','reconciliations') THEN resp:=office_private.inst_finance(p_workspace_id,CASE r WHEN 'funds' THEN 'save_fund' WHEN 'budgets' THEN 'save_budget' WHEN 'contributions' THEN 'save_contribution' WHEN 'payment_requests' THEN 'save_payment_request' WHEN 'bank_lines' THEN 'save_bank_line' ELSE 'save_reconciliation' END,p_payload);
 ELSIF p_action IN('save_record','save_private') THEN IF p_action='save_record' AND r IN('funds','budgets','contributions','payment_requests','bank_lines','reconciliations') THEN resp:=office_private.inst_finance(p_workspace_id,CASE r WHEN 'funds' THEN 'save_fund' WHEN 'budgets' THEN 'save_budget' WHEN 'contributions' THEN 'save_contribution' WHEN 'payment_requests' THEN 'save_payment_request' WHEN 'bank_lines' THEN 'save_bank_line' ELSE 'save_reconciliation' END,p_payload); ELSIF r NOT IN('organizations','branches','bodies','people','appointments','meetings','resolutions','funds','budgets','contributions','payment_requests','bank_lines','reconciliations','facilities','assets','asset_moves','programmes','events','attendance','staff_assignments','credentials','filings','evidence','safeguarding','privacy_requests') THEN RAISE EXCEPTION 'Unknown Institutions resource' USING ERRCODE='22023'; END IF; cap:=office_private.inst_cap_for_resource(r); IF cap IS NULL OR NOT office_private.inst_cap(p_workspace_id,cap) THEN RAISE EXCEPTION 'Resource capability denied' USING ERRCODE='42501'; END IF; branch:=NULLIF(d->>'branch_id','')::uuid; PERFORM office_private.inst_assert_scope(p_workspace_id,branch); IF p_action='save_private' AND r NOT IN('people','attendance','safeguarding') THEN RAISE EXCEPTION 'save_private is restricted to encrypted resources' USING ERRCODE='22023'; END IF; IF r IN('people','attendance','safeguarding') THEN IF p_action<>'save_private' OR d->>'lawful_basis' IS NULL OR d->>'notice_reference' IS NULL OR d->>'retention_until' IS NULL OR d->>'nonce' IS NULL OR d->>'ciphertext' IS NULL THEN RAISE EXCEPTION 'Private record lawful basis, notice, retention and ciphertext required' USING ERRCODE='22023'; END IF; SELECT * INTO settings FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id; IF NOT(settings.private_data_enabled AND settings.storage_review_state='approved') OR NOT EXISTS(SELECT 1 FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind=CASE WHEN r='safeguarding' THEN 'safeguarding' ELSE 'people' END AND configured) THEN RAISE EXCEPTION 'Private gate closed' USING ERRCODE='55000'; END IF; END IF; IF p_action='save_private' AND NOT (p_payload ? 'id') THEN RAISE EXCEPTION 'Private create requires top-level id' USING ERRCODE='22023'; END IF;
 IF p_action='save_record' AND p_payload ? 'expected_version' AND ((p_payload->>'expected_version') IS NULL OR (p_payload->>'expected_version')::bigint<1) THEN RAISE EXCEPTION 'Positive expected_version required' USING ERRCODE='22023'; END IF;
 IF p_action='save_private' AND p_payload ? 'expected_version' AND ((p_payload->>'expected_version') IS NULL OR (p_payload->>'expected_version')::bigint<1) THEN RAISE EXCEPTION 'Positive expected_version required' USING ERRCODE='22023'; END IF;
 PERFORM office_private.inst_validate_data(p_workspace_id,r,d,p_action='save_private');
 record_id:=COALESCE(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); SELECT rec.* INTO x FROM public.office_institutions_records rec WHERE rec.workspace_id=p_workspace_id AND rec.resource=r AND rec.id=record_id FOR UPDATE; IF FOUND THEN expected:=NULLIF(p_payload->>'expected_version','')::bigint; IF expected IS NULL OR expected<>x.version THEN RAISE EXCEPTION 'Stale version' USING ERRCODE='40001'; END IF; IF r='organizations' AND NOT (d ? 'code' AND d ? 'name' AND d ? 'jurisdiction' AND d ? 'legal_form' AND d ? 'registration_authority' AND d ? 'registration_reference' AND d ? 'constitution_reference') THEN RAISE EXCEPTION 'Required organization fields missing' USING ERRCODE='22023'; END IF; IF r='evidence' OR (p_action='save_record' AND x.status IS DISTINCT FROM office_private.inst_initial(r)) THEN RAISE EXCEPTION 'Only initial-state records are editable; use workflow transitions' USING ERRCODE='55000'; END IF; IF p_action='save_private' AND r IN('people','attendance','safeguarding') THEN IF NULLIF(x.data->>'branch_id','') IS DISTINCT FROM NULLIF(d->>'branch_id','') OR NULLIF(x.data->>'code','') IS DISTINCT FROM NULLIF(d->>'code','') THEN RAISE EXCEPTION 'Private record branch and code are immutable' USING ERRCODE='55000'; END IF; END IF; FOR key_name IN SELECT jsonb_object_keys(x.data) WHERE key_name LIKE '%\_id' OR key_name IN('jurisdiction','legal_form','registration_authority') LOOP IF NULLIF(x.data->>key_name,'') IS DISTINCT FROM NULLIF(d->>key_name,'') THEN RAISE EXCEPTION 'Immutable relation field %',key_name USING ERRCODE='55000'; END IF; END LOOP; merged:=d; FOREACH key_name IN ARRAY ARRAY['asset_version','approved_by','reviewed_by','verified_by','source_branch_id'] LOOP IF x.data ? key_name AND NOT (merged ? key_name) THEN merged:=merged||jsonb_build_object(key_name,x.data->key_name); END IF; END LOOP; UPDATE public.office_institutions_records rec SET data=merged,version=x.version+1,updated_at=now() WHERE rec.workspace_id=p_workspace_id AND rec.resource=r AND rec.id=record_id; v:=x.version+1; st:=x.status; ELSE IF p_payload ? 'expected_version' THEN RAISE EXCEPTION 'Create cannot include expected_version' USING ERRCODE='22023'; END IF; st:=office_private.inst_initial(r); INSERT INTO public.office_institutions_records(id,workspace_id,resource,data,status,created_by) VALUES(record_id,p_workspace_id,r,d,st,auth.uid()); v:=1; END IF; resp:=jsonb_build_object('id',record_id,'version',v,'status',st);
 ELSIF p_action='transition_record' THEN IF r IN('funds','budgets','contributions','payment_requests','bank_lines','reconciliations') THEN
   IF p_payload->>'to_state'='submitted' AND r='budgets' THEN resp:=office_private.inst_finance(p_workspace_id,'submit_budget',p_payload);
   ELSIF p_payload->>'to_state'='submitted' AND r='payment_requests' THEN resp:=office_private.inst_finance(p_workspace_id,'submit_payment',p_payload);
   ELSIF p_payload->>'to_state'='submitted' AND r='reconciliations' THEN resp:=office_private.inst_finance(p_workspace_id,'submit_reconciliation',p_payload);
   ELSIF p_payload->>'to_state'='approved' AND r='budgets' THEN resp:=office_private.inst_finance(p_workspace_id,'approve_budget',p_payload);
   ELSIF p_payload->>'to_state'='matched' AND r='bank_lines' THEN resp:=office_private.inst_finance(p_workspace_id,'match_bank_line',p_payload);
   ELSIF p_payload->>'to_state'='reviewed' AND r='reconciliations' THEN resp:=office_private.inst_finance(p_workspace_id,'review_reconciliation',p_payload);
   ELSIF p_payload->>'to_state'='closed' AND r='reconciliations' THEN resp:=office_private.inst_finance(p_workspace_id,'close_reconciliation',p_payload);
   ELSE RAISE EXCEPTION 'Invalid finance transition' USING ERRCODE='22023'; END IF;
 ELSE resp:=office_private.inst_workflow(p_workspace_id,p_action,p_payload); END IF;
 ELSIF p_action IN('create_report','export_report') THEN EXECUTE 'SELECT office_private.inst_reports($1,$2,$3)' INTO resp USING p_workspace_id,p_action,p_payload;
 ELSIF p_action='post_asset_move' THEN EXECUTE 'SELECT office_private.inst_workflow($1,$2,$3)' INTO resp USING p_workspace_id,p_action,p_payload;
 ELSIF p_action IN('configure_settings','configure_private_key','record_storage_review','review_storage','set_private_gate') THEN resp:=office_private.inst_settings(p_workspace_id,p_action,p_payload);
 ELSIF p_action IN('post_contribution','void_contribution','approve_payment','post_payment','close_reconciliation') THEN EXECUTE 'SELECT office_private.inst_finance($1,$2,$3)' INTO resp USING p_workspace_id,p_action,p_payload;
 ELSE EXECUTE 'SELECT office_private.inst_workflow($1,$2,$3)' INTO resp USING p_workspace_id,p_action,p_payload; END IF; END IF;
 UPDATE public.office_institutions_idempotency SET response=resp WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=k; INSERT INTO public.office_institutions_audit(workspace_id,actor_id,resource,action,entity_id,metadata) VALUES(p_workspace_id,auth.uid(),COALESCE(r,'settings'),p_action,NULLIF(resp->>'id','')::uuid,jsonb_build_object('version',resp->'version','status',resp->'status')); RETURN resp;
END $$;
GRANT EXECUTE ON FUNCTION public.office_institutions_read(uuid,text,jsonb,integer,integer),public.office_institutions_command(uuid,text,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION office_private.inst_initial(text),office_private.inst_cap_for_resource(text),office_private.inst_safe_row(record),office_private.inst_member(uuid),office_private.inst_role(uuid),office_private.inst_cap(uuid,text),office_private.inst_scope(uuid,uuid),office_private.inst_assert_scope(uuid,uuid),office_private.inst_require(uuid),office_private.inst_audit_immutable() FROM PUBLIC,anon,authenticated;
COMMIT;
